"use strict";(self.webpackChunkdeveloper_page=self.webpackChunkdeveloper_page||[]).push([[846],{3622:function(e,t,a){a.r(t),a.d(t,{Head:function(){return o}});var n=a(6540);t.default=()=>n.createElement(n.Fragment,null,n.createElement("article",{className:"privacy"},n.createElement("p",null,"Last updated: 25.10.2026"),n.createElement("h2",null,"1. Introduction"),n.createElement("p",null,"Daylit is a mobile application that shows how long the day is where you are, how it changes from day to day, and when the sun rises and sets. We keep data collection to the minimum needed to run and improve the app, and we explain all of it below."),n.createElement("p",null,"Daylit does not require an account. We never ask for your name, email address or password, we do not show ads, and we do not sell your data."),n.createElement("h2",null,"2. Location"),n.createElement("p",null,"If you allow location access, Daylit uses your location only on your device: to calculate sunrise, sunset and day length, and to find the nearest city in a database built into the app. Your coordinates are never sent to us, to analytics or to any other third party. City search also runs entirely on your device."),n.createElement("p",null,"You can use Daylit without location access by choosing a city yourself, and you can change the permission at any time in the iOS Settings app."),n.createElement("h2",null,"3. Data Stored on Your Device"),n.createElement("p",null,"Your chosen city, favorite and recent cities, the city you compare with, notification preferences and other settings are stored only on your device. Widgets read the same data on your device to show your day length. We do not upload any of it to our servers. Deleting the app deletes this data."),n.createElement("h2",null,"4. Analytics"),n.createElement("p",null,"To understand which features are used and to improve the app, Daylit uses ",n.createElement("b",null,"Google Analytics for Firebase"),". It collects anonymous usage events, for example:"),n.createElement("ul",null,n.createElement("li",null,"a city chosen, and whether it was your current location or a favorite (not which city);"),n.createElement("li",null,"comparisons started, favorites added or removed, the timeline explored;"),n.createElement("li",null,"notifications turned on or off and opened;"),n.createElement("li",null,"paywall views, plan selections and purchase or restore taps;"),n.createElement("li",null,"the app shared or a review requested.")),n.createElement("p",null,"Daylit also records a few app settings: the language, whether location access and notifications are allowed, and how many favorite cities you have. Firebase collects technical information as well: a random app instance identifier, device model, iOS version, app version and approximate country. Daylit does ",n.createElement("b",null,"not")," use the advertising identifier (IDFA) and does not track you across other apps or websites."),n.createElement("p",null,"You can turn analytics off at any time in"," ",n.createElement("b",null,"Settings → Privacy → Share usage data"),". Google processes this data on our behalf and retains it for a limited period (no more than 14 months). Learn more in"," ",n.createElement("a",{href:"https://policies.google.com/privacy"},"Google’s Privacy Policy"),"."),n.createElement("h2",null,"5. Purchases and Subscriptions"),n.createElement("p",null,"Daylit Plus is offered as an auto-renewable subscription or a one-time purchase. Payments are processed entirely by ",n.createElement("b",null,"Apple"),". We never see or store your payment details."),n.createElement("p",null,"To check whether you have access to Daylit Plus and to restore purchases, Daylit uses ",n.createElement("b",null,"RevenueCat"),". RevenueCat receives an anonymous app user identifier, your purchase and subscription history (product, dates, store country and status) and basic device information. Learn more in"," ",n.createElement("a",{href:"https://www.revenuecat.com/privacy"},"RevenueCat’s Privacy Policy"),"."),n.createElement("h2",null,"6. Notifications"),n.createElement("p",null,"Daylight notifications, such as the solstices and the first minute of light gained, are local notifications scheduled on your device. We do not use push notification servers."),n.createElement("h2",null,"7. Third-Party Content"),n.createElement("p",null,"City names and locations come from"," ",n.createElement("a",{href:"https://www.geonames.org"},"GeoNames")," under the CC BY 4.0 license and are built into the app. Looking up a city does not send anything to GeoNames."),n.createElement("h2",null,"8. Contacting Support"),n.createElement("p",null,"If you email us, for example to report a bug, we receive your email address and whatever you choose to include in the message, along with the app and iOS version the app adds to it. We use it only to answer you."),n.createElement("h2",null,"9. Your Rights"),n.createElement("p",null,"Depending on where you live (for example, under the GDPR in the European Union), you have the right to access, correct or delete your data, and to object to its processing. We process analytics data based on our legitimate interest in improving the app, and purchase data to provide the service you paid for. Because we do not know who you are, we may ask for details that help us find your data. Contact us at the address below."),n.createElement("h2",null,"10. Children’s Privacy"),n.createElement("p",null,"Daylit is not directed at children under 13, and we do not knowingly collect personal information from them. If you believe a child has provided us with personal information, please contact us and we will delete it."),n.createElement("h2",null,"11. Changes to This Policy"),n.createElement("p",null,"We may update this policy when the app changes. The updated version will be posted on this page with a new “Last updated” date."),n.createElement("h2",null,"12. Contact"),n.createElement("p",null,"If you have any questions about this privacy policy, reach out at ",n.createElement("a",{href:"mailto:raman@lukashyk.dev"},"raman@lukashyk.dev"),".")));const o=()=>n.createElement(n.Fragment,null,n.createElement("title",null,"Daylit – Privacy Policy"),n.createElement("meta",{name:"description",content:"How Daylit handles your data: location kept on your device, anonymous analytics and purchases."}))}}]);
